import {CATEGORIES,localDate,validDate,amountFen,money,validateRecord,summarize,filtered,backupData,validateBackup,csv} from './core.js';
const $=id=>document.getElementById(id),all=s=>[...document.querySelectorAll(s)];
let db,records=[],budgets=[],page='home',entryType='expense',categoryId='',statType='expense',limit=50,dirty=false,saving=false,confirmAction=null,toastTimer;
const colors=['#b83d72','#7b65a3','#cb7955','#63858d','#b19238','#975475','#5874a4','#a56f63'];
const titles={home:['好好生活，慢慢积攒','从今天的一笔开始，把生活记成喜欢的样子。','生活概览'],records:['每一笔，都是生活','认真记下的小日子，都在这里。','收支明细'],stats:['看见生活的轮廓','了解钱的去向，也了解自己的喜好。','消费统计'],settings:['照顾好你的小账本','把记录好好收藏，让每一份回忆安心留下。','账本设置']};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cat=id=>CATEGORIES.find(c=>c.id===id);
const month=()=>$('month').value;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4000)}
function errorText(e){return e?.name==='QuotaExceededError'?'浏览器空间不足，未保存。请先导出备份并释放空间。':e?.message||'操作失败，请重试';}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('petal-ledger-v1',1);req.onupgradeneeded=()=>{req.result.createObjectStore('records',{keyPath:'id'});req.result.createObjectStore('budgets',{keyPath:'month'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('数据库升级被其他页面阻止，请关闭其他账本页面后刷新'));});}
function readStore(name){return new Promise((resolve,reject)=>{const tx=db.transaction(name),req=tx.objectStore(name).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});}
function transact(stores,mutate){return new Promise((resolve,reject)=>{try{const tx=db.transaction(stores,'readwrite');tx.oncomplete=()=>resolve();tx.onabort=()=>reject(tx.error||Error('数据未写入，请重试'));tx.onerror=()=>{};try{mutate(tx)}catch(e){tx.abort();reject(e)}}catch(e){reject(e)}});}
async function reload(){[records,budgets]=await Promise.all([readStore('records'),readStore('budgets')]);render();}
function empty(title,description,action=false){return `<div class="empty"><span class="empty-icon" aria-hidden="true">✿</span><h3>${esc(title)}</h3><p>${esc(description)}</p>${action?'<button class="secondary" data-add>＋ 记下第一笔</button>':''}</div>`;}
function rows(items){return items.map(r=>`<button class="row" data-edit="${esc(r.id)}" aria-label="编辑${esc(cat(r.categoryId).name)}${r.type==='expense'?'支出':'收入'}${money(r.amountFen)}元"><span class="category-icon" aria-hidden="true">${cat(r.categoryId).icon}</span><span class="row-info"><span class="row-title">${esc(cat(r.categoryId).name)}</span><span class="row-note">${esc(r.note||'日常的小记录')} · ${r.occurredDate}</span></span><span class="row-amount ${r.type}">${r.type==='expense'?'−':'＋'} ${money(r.amountFen)}<small>${r.type==='expense'?'支出':'收入'}</small></span></button>`).join('');}
function currentSummary(){return summarize(records,month());}
function budgetRender(s){const b=budgets.find(b=>b.month===month());$('edit-budget').textContent=b?'调整预算 ↗':'设置预算 ↗';if(!b){$('budget-content').innerHTML=empty('给这个月一个小计划','设置支出预算，随时了解还能花多少。')+'<button class="secondary" data-budget>设置本月预算</button>';return;}
 const ratio=s.expense/b.amountFen,remaining=b.amountFen-s.expense;
 $('budget-content').innerHTML=`<div class="budget-amount">¥ ${money(Math.abs(remaining))}<small>${remaining<0?'已超支':'剩余可用'}</small></div><div class="progress" role="progressbar" aria-label="月度预算使用" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(ratio*100))}" aria-valuetext="已使用 ${Math.round(ratio*100)}%"><span style="width:${Math.min(100,ratio*100)}%"></span></div><div class="budget-meta"><span>已支出 ¥${money(s.expense)}</span><span>总预算 ¥${money(b.amountFen)}</span></div><p class="budget-hint ${ratio>=.8?'warning':''}">${ratio>=1?`⚠ ${remaining===0?'预算已用完':'本月已超出预算 ¥'+money(-remaining)}`:ratio>=.8?'⚠ 预算已使用 '+Math.round(ratio*100)+'%':'♡ 已使用 '+Math.round(ratio*100)+'%，给喜欢的生活留一点余地。'}</p>`;
}
function breakdown(type){const map={};for(const r of records)if(r.type===type&&r.occurredDate.startsWith(month()+'-'))map[r.categoryId]=(map[r.categoryId]||0)+r.amountFen;return Object.entries(map).sort((a,b)=>b[1]-a[1]);}
function ring(data,total){if(!total)return empty('还没有可分析的记录','记下第一笔，生活的轮廓就会慢慢清晰。');let offset=0;const stops=data.map(([,n],i)=>{const a=offset;offset+=n/total*100;return `${colors[i%colors.length]} ${a}% ${offset}%`}).join(',');return `<div class="ring-wrap"><div class="ring" role="img" aria-label="分类占比，下方有详细金额与比例" style="background:conic-gradient(${stops})"><div class="ring-center"><small>合计（元）</small><strong>${money(total)}</strong></div></div><div class="legend">${data.map(([id,n],i)=>`<div class="legend-item"><span class="dot" style="background:${colors[i%colors.length]}"></span>${esc(cat(id).name)}<b>${(n/total*100).toFixed(1)}%</b></div>`).join('')}</div></div>`;}
function renderHome(){const s=currentSummary();$('month-expense').textContent='¥ '+money(s.expense);$('month-income').textContent='¥ '+money(s.income);$('month-balance').textContent='¥ '+money(s.balance);$('today-amount').textContent='¥ '+money(s.todayExpense);$('today-date').textContent=localDate()+' · 今天的支出';budgetRender(s);const recent=filtered(records,{month:month()}).slice(0,5);$('recent-list').innerHTML=recent.length?rows(recent):empty('第一笔小美好，等你来记录','今天的咖啡、午餐，或是一份小礼物。',true);$('home-chart').innerHTML=ring(breakdown('expense'),s.expense);}
function getFiltered(){return filtered(records,{month:month(),type:$('filter-type').value,category:$('filter-category').value,search:$('search').value.trim()});}
function renderRecords(){const list=getFiltered();let income=0,expense=0;list.forEach(r=>r.type==='income'?income+=r.amountFen:expense+=r.amountFen);$('record-summary').textContent=`共 ${list.length} 笔 · 支出 ¥${money(expense)} · 收入 ¥${money(income)}`;let html='',previous='';const dayTotals={};for(const r of list){dayTotals[r.occurredDate]??={income:0,expense:0};dayTotals[r.occurredDate][r.type]+=r.amountFen;}for(const r of list.slice(0,limit)){if(previous!==r.occurredDate){previous=r.occurredDate;const day=dayTotals[previous];html+=`<div class="day-heading"><strong>${previous}</strong><small>支出 ¥${money(day.expense)} · 收入 ¥${money(day.income)}</small></div>`;}html+=rows([r]);}$('record-list').innerHTML=html||empty('没有找到记录','试试清除筛选，或记下新的一笔。',true);$('load-more').hidden=list.length<=limit;}
function renderStats(){const type=statType,s=currentSummary(),data=breakdown(type),total=s[type],name=type==='expense'?'支出':'收入';$('category-title').textContent=name+'分类';$('trend-title').textContent='每日'+name+'趋势';$('stats-total').textContent='合计 ¥'+money(total);$('stats-chart').innerHTML=ring(data,total);$('category-details').innerHTML=data.length?data.map(([id,n],i)=>`<div class="category-line"><span>${cat(id).icon} ${esc(cat(id).name)}</span><div class="progress"><span style="width:${n/total*100}%;background:${colors[i%colors.length]}"></span></div><b>¥ ${money(n)}</b><small>${(n/total*100).toFixed(1)}%</small></div>`).join(''):empty('分类明细还空着','有了记录，这里就会显示金额与占比。');
 const [year,m]=month().split('-').map(Number),days=new Date(year,m,0).getDate(),daily=Array(days).fill(0);for(const r of records)if(r.type===type&&r.occurredDate.startsWith(month()+'-'))daily[Number(r.occurredDate.slice(-2))-1]+=r.amountFen;
 if(!total){$('trend-chart').innerHTML=empty('还没有趋势数据','每天记一点，就能看见消费的变化。');return;}
 const max=Math.max(...daily),w=500,h=200,left=50,bottom=165,top=15,dx=430/(days-1);const points=daily.map((n,i)=>`${left+i*dx},${bottom-n/max*(bottom-top)}`).join(' ');const grid=[0,.5,1].map(p=>`<line x1="50" y1="${bottom-p*150}" x2="480" y2="${bottom-p*150}" stroke="#f1e3eb"/><text x="43" y="${bottom-p*150+4}" text-anchor="end" class="trend-value">${(max*p/100).toLocaleString('zh-CN',{maximumFractionDigits:0})}</text>`).join('');$('trend-chart').innerHTML=`<svg class="trend-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="每日${name}趋势，展开下方数据查看具体金额">${grid}<polygon points="50,165 ${points} 480,165" fill="#fce8f1"/><polyline points="${points}" fill="none" stroke="#b83d72" stroke-width="2.5" stroke-linejoin="round"/><text x="50" y="190" class="trend-value">1 日</text><text x="255" y="190" class="trend-value">${Math.ceil(days/2)} 日</text><text x="480" y="190" text-anchor="end" class="trend-value">${days} 日</text></svg><p class="chart-caption">日均 ¥${money(Math.round(total/days))} · 单日最高 ¥${money(max)}（按完整自然月计算）</p><details class="daily-table"><summary>查看每日金额</summary>${daily.map((n,i)=>`<div class="daily-line"><span>${month()}-${String(i+1).padStart(2,'0')}</span><span>¥${money(n)}</span></div>`).join('')}</details>`;}
function render(){renderHome();if(page==='records')renderRecords();if(page==='stats')renderStats();$('data-count').textContent=`当前共 ${records.length} 笔记录 · ${budgets.length} 个月度预算`;}
function go(next){if(!titles[next])return;page=next;all('.page').forEach(el=>el.hidden=el.id!==page);all('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});const [title,desc,crumb]=titles[page];$('page-title').textContent=title;$('page-description').textContent=desc;$('breadcrumb').textContent=crumb;$('period-bar').hidden=page==='settings';render();}
function fillFilterCategories(){const type=$('filter-type').value,old=$('filter-category').value;$('filter-category').innerHTML='<option value="">全部分类</option>'+CATEGORIES.filter(c=>!type||c.type===type).map(c=>`<option value="${c.id}">${c.name}${!type?' · '+(c.type==='expense'?'支出':'收入'):''}</option>`).join('');if([...$('filter-category').options].some(o=>o.value===old))$('filter-category').value=old;}
function entryCategories(){all('[data-type]').forEach(b=>{const active=b.dataset.type===entryType;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});$('entry-categories').innerHTML=CATEGORIES.filter(c=>c.type===entryType).map(c=>`<button type="button" class="category-choice ${c.id===categoryId?'selected':''}" data-category="${c.id}" aria-pressed="${c.id===categoryId}"><span aria-hidden="true">${c.icon}</span>${c.name}</button>`).join('');}
function openEntry(id){if(!db){toast('本地数据库尚不可用，请查看页面提示');return}const r=records.find(r=>r.id===id);$('entry-form').reset();all('#entry-form .field-error').forEach(e=>e.textContent='');$('record-id').value=r?.id||'';entryType=r?.type||'expense';categoryId=r?.categoryId||'';$('amount').value=r?(r.amountFen/100).toFixed(2):'';$('date').value=r?.occurredDate||localDate();$('date').max=localDate();$('date').min='0001-01-01';$('note').value=r?.note||'';$('delete-record').hidden=!r;$('entry-title').textContent=r?'修改这一笔':'记下生活的一笔';entryCategories();dirty=false;$('entry-dialog').showModal();$('amount').focus();}
function closeEntry(){if(saving)return;if(dirty){ask('放弃未保存的修改？','这一笔还没有保存，关闭后输入内容会丢失。',async()=>{dirty=false;$('entry-dialog').close()});}else $('entry-dialog').close();}
function ask(title,message,action,{importing=false}={}){$('confirm-title').textContent=title;$('confirm-message').textContent=message;$('confirm-error').textContent='';$('import-backup-action').hidden=!importing;$('confirm-ok').textContent=importing?'确认替换全部数据':'确认';confirmAction=action;$('confirm-dialog').showModal();$('confirm-cancel').focus();}
async function saveEntry(e){e.preventDefault();if(saving)return;all('#entry-form .field-error').forEach(e=>e.textContent='');let amount;try{amount=amountFen($('amount').value)}catch(e){$('amount-error').textContent=e.message;$('amount').focus();return}if(!categoryId){$('category-error').textContent='请选择一个分类';return}if(!validDate($('date').value)){$('date-error').textContent='请选择有效日期，且不能晚于今天';$('date').focus();return}try{const old=records.find(r=>r.id===$('record-id').value),now=new Date().toISOString();const r=validateRecord({id:old?.id||crypto.randomUUID(),type:entryType,amountFen:amount,categoryId,occurredDate:$('date').value,note:$('note').value,createdAt:old?.createdAt||now,updatedAt:now});saving=true;$('save-record').disabled=true;await transact(['records'],tx=>tx.objectStore('records').put(r));dirty=false;$('entry-dialog').close();await reload();toast('已记好这一笔 ♡');}catch(e){$('entry-error').textContent=errorText(e)}finally{saving=false;$('save-record').disabled=false;}}
function openBudget(){if(!db){toast('本地数据库尚不可用');return}const b=budgets.find(b=>b.month===month());$('budget-title').textContent=month()+' 月度预算';$('budget-amount').value=b?(b.amountFen/100).toFixed(2):'';$('budget-error').textContent='';$('cancel-budget').hidden=!b;$('budget-dialog').showModal();$('budget-amount').focus();}
async function saveBudget(e){e.preventDefault();if(saving)return;try{const b={month:month(),amountFen:amountFen($('budget-amount').value),updatedAt:new Date().toISOString()};saving=true;$('save-budget').disabled=true;await transact(['budgets'],tx=>tx.objectStore('budgets').put(b));$('budget-dialog').close();await reload();toast('预算已保存');}catch(e){$('budget-error').textContent=errorText(e)}finally{saving=false;$('save-budget').disabled=false;}}
function download(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function backup(){download(JSON.stringify(backupData(records,budgets),null,2),`花花账本备份-${localDate()}.json`,'application/json');}
async function importFile(e){const file=e.target.files[0];e.target.value='';if(!file)return;if(!db){toast('数据库不可用，无法导入');return}try{if(file.size>30*1024*1024)throw Error('备份文件不能超过 30 MB');const data=validateBackup(JSON.parse(await file.text()));const sum=data.records.reduce((n,r)=>n+(r.type==='expense'?r.amountFen:0),0);ask('确认恢复这份账本？',`文件：${file.name}\n包含 ${data.records.length} 笔记录、${data.budgets.length} 个月度预算。\n全部支出合计 ¥${money(sum)}。\n恢复将替换当前 ${records.length} 笔记录及全部预算。建议先点击下方按钮下载当前备份。`,async()=>{await transact(['records','budgets'],tx=>{const rs=tx.objectStore('records'),bs=tx.objectStore('budgets');rs.clear();bs.clear();data.records.forEach(r=>rs.put(r));data.budgets.forEach(b=>bs.put(b));});await reload();toast('账本已完整恢复');},{importing:true});}catch(e){toast('导入失败：'+errorText(e));}}
$('month').value=localDate().slice(0,7);fillFilterCategories();
all('[data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));all('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));$('new-record').onclick=()=>openEntry();$('mobile-add').onclick=()=>openEntry();
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit]'),add=e.target.closest('[data-add]'),budget=e.target.closest('[data-budget]'),category=e.target.closest('[data-category]');if(edit)openEntry(edit.dataset.edit);if(add)openEntry();if(budget)openBudget();if(category){categoryId=category.dataset.category;dirty=true;entryCategories();$('category-error').textContent='';}});
all('[data-type]').forEach(b=>b.onclick=()=>{if(entryType===b.dataset.type)return;entryType=b.dataset.type;categoryId='';dirty=true;entryCategories()});
$('entry-form').addEventListener('input',()=>dirty=true);$('entry-form').onsubmit=saveEntry;$('close-entry').onclick=closeEntry;$('entry-dialog').addEventListener('cancel',e=>{e.preventDefault();closeEntry()});$('entry-dialog').addEventListener('click',e=>{if(e.target===$('entry-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeEntry();}});
$('delete-record').onclick=()=>{const id=$('record-id').value;ask('删除这笔记录？','删除后将同步更新汇总和预算，预算设置会保留。',async()=>{await transact(['records'],tx=>tx.objectStore('records').delete(id));dirty=false;$('entry-dialog').close();await reload();toast('记录已删除')})};
$('confirm-cancel').onclick=()=>$('confirm-dialog').close();$('confirm-dialog').addEventListener('cancel',e=>{if(saving)e.preventDefault()});$('confirm-ok').onclick=async()=>{if(saving||!confirmAction)return;saving=true;$('confirm-ok').disabled=true;$('confirm-cancel').disabled=true;try{await confirmAction();$('confirm-dialog').close();}catch(e){$('confirm-error').textContent=errorText(e)}finally{saving=false;$('confirm-ok').disabled=false;$('confirm-cancel').disabled=false;}};
$('edit-budget').onclick=openBudget;$('close-budget').onclick=()=>{if(!saving)$('budget-dialog').close()};$('budget-dialog').addEventListener('cancel',e=>{if(saving)e.preventDefault()});$('budget-form').onsubmit=saveBudget;$('cancel-budget').onclick=()=>{const m=month();ask('取消本月预算？','只移除 '+m+' 的预算，收支记录会保留。',async()=>{await transact(['budgets'],tx=>tx.objectStore('budgets').delete(m));$('budget-dialog').close();await reload();toast('预算已取消')})};
function changeMonth(delta){const [y,m]=month().split('-').map(Number);let total=y*12+m-1+delta;if(total<12||total>119999)return;const year=Math.floor(total/12),mm=total%12+1;$('month').value=String(year).padStart(4,'0')+'-'+String(mm).padStart(2,'0');limit=50;render();}
$('prev-month').onclick=()=>changeMonth(-1);$('next-month').onclick=()=>changeMonth(1);$('month').onchange=()=>{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month())||month()<'0001-01')$('month').value=localDate().slice(0,7);limit=50;render()};$('this-month').onclick=()=>{$('month').value=localDate().slice(0,7);limit=50;render()};$('filter-type').onchange=()=>{fillFilterCategories();limit=50;renderRecords()};$('filter-category').onchange=()=>{limit=50;renderRecords()};$('search').oninput=()=>{limit=50;renderRecords()};$('clear-filter').onclick=()=>{$('filter-type').value='';$('search').value='';fillFilterCategories();$('filter-category').value='';limit=50;renderRecords()};$('load-more').onclick=()=>{limit+=50;renderRecords()};$('export-csv').onclick=()=>{download(csv(getFiltered()),`花花账本明细-${month()}.csv`,'text/csv;charset=utf-8');toast('已导出当前筛选范围的明细')};
all('[data-stat]').forEach(b=>b.onclick=()=>{statType=b.dataset.stat;all('[data-stat]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderStats()});$('backup').onclick=backup;$('before-import-backup').onclick=backup;$('import-file').onchange=importFile;
window.addEventListener('beforeunload',e=>{if(dirty||saving){e.preventDefault();e.returnValue=''}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){$('date').max=localDate();if(db&&!saving)reload().catch(()=>toast('刷新数据失败，请重新打开页面'));}});
go('home');
try{db=await openDB();db.onversionchange=()=>{db.close();db=null;$('storage-warning').hidden=false;$('storage-warning').textContent='账本数据库已在其他页面更新，请刷新后继续。'};await reload();}catch(e){$('storage-warning').hidden=false;$('storage-warning').textContent='本地数据库不可用，当前无法保存记录。请使用正常浏览模式，并通过固定的 localhost 或 HTTPS 地址访问。'+errorText(e);}
